export{ModalCargoCtrl};function ModalCargoCtrl($scope,$uibModalInstance,mS,tS,params){function onInit(){params&&params.idCargo>0&&($scope.tipoRegistro=2,$scope.data=params)}$scope.tipoRegistro=1,$scope.data={},onInit(),$scope.obtenerCodigo=function(){$scope.data.descripcion&&1===$scope.tipoRegistro&&($scope.data.codigo=$scope.data.descripcion.slice(0,3))},$scope.saveAndUpdate=function(){const titulo=1===$scope.tipoRegistro?"Guardar":"Actualizar";if(!$scope.data.descripcion)return void tS.toastr("warning","Ingrese la Descripción",titulo);if(!$scope.data.codigo)return void tS.toastr("warning","Ingrese el Códgio",titulo);const url=1===$scope.tipoRegistro?"/Cargo/Post":"/Cargo/Put?id="+$scope.data.idCargo,method=1===$scope.tipoRegistro?"post":"put";showLoader(),mS.getData(method,url,$scope.data).then(response=>{hideLoader(),"0"===response.id&&tS.toastr("warning",response.message,response.titleSms),"1"===response.id&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response))})},$scope.closeModal=function(){$uibModalInstance.close()}}ModalCargoCtrl.$inject=["$scope","$uibModalInstance","mainService","toastService","params"];